import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1

    results = []

    for _ in range(t):
        l = int(data[index])
        r = int(data[index + 1])
        index += 2

        if (r - l + 1) % 2 == 0:
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
